m("field.flow.type","Flow type","How the flow looks: dashes, dots, beads, arrows or liquid.");m("field.flow.color","Flow color","The colour of the flow (#RRGGBB). Empty keeps the line colour.");m("field.flow.width","Line width","The width of the flow line in pixels. Empty keeps the line width of the object.");m("field.speedExpr","Speed","An expression for the speed. 1 is normal, 2 is twice as fast. A value of 0 or less stops the flow. Optional.");m("field.media.mode","Media mode",'"Play" plays while the expression is true. "Pause" pauses while it is true.');
